import pandas as pd
import numpy as np

# Load the data
data = pd.read_csv('chunks_csv/moran_local_2023_ghg.csv')
adjacency = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Compute neighborhood means
neighborhood_means = {}
for index, row in data.iterrows():
    neighbors = adjacency[adjacency['borough'] == row['borough']]
    neighbor_values = data[data['borough'].isin(neighbors['neighbor'])]['GHG_value']
    neighborhood_means[row['borough']] = np.mean(neighbor_values)

# Compute local Moran's I
local_morans = {}
for index, row in data.iterrows():
    neighbors = adjacency[adjacency['borough'] == row['borough']]
    neighbor_values = data[data['borough'].isin(neighbors['neighbor'])]['GHG_value']
    local_morans[row['borough']] = np.corrcoef(row['GHG_value'], neighborhood_means[row['borough']])[0, 1]

# Determine hot and cold spots
hot_spots = {}
cold_spots = {}
for borough, moran in local_morans.items():
    if data[data['borough'] == borough]['GHG_value'].values[0] > np.mean(data['GHG_value']) and moran > 0.5:
        hot_spots[borough] = moran
    elif data[data['borough'] == borough]['GHG_value'].values[0] < np.mean(data['GHG_value']) and moran < -0.5:
        cold_spots[borough] = moran

# Perform permutation test
p_values = {}
for borough, moran in hot_spots.items():
    p_values[borough] = np.mean([np.corrcoef(np.random.permutation(data[data['borough'] == borough]['GHG_value']), np.random.permutation(neighborhood_means[borough]))[0, 1] for _ in range(500)])
for borough, moran in cold_spots.items():
    p_values[borough] = np.mean([np.corrcoef(np.random.permutation(data[data['borough'] == borough]['GHG_value']), np.random.permutation(neighborhood_means[borough]))[0, 1] for _ in range(500)])

# Report results
print(f'data_points_used = {len(data)}')
for borough, moran in hot_spots.items():
    print(f'FINAL ANSWER: {borough} (HH, statistical method={moran:.4f}, p-value={p_values[borough]:.4f})')
for borough, moran in cold_spots.items():
    print(f'FINAL ANSWER: {borough} (LL, statistical method={moran:.4f}, p-value={p_values[borough]:.4f})')
if not hot_spots and not cold_spots:
    print('FINAL ANSWER: none')
